where w.del_flag = '0' and w.tenant_id = #{tenantId}

    and w.event_type = #{eventType}


    and w.enabled = #{enabled}

order by w.update_time desc


where w.del_flag = '0'
  and w.tenant_id = #{tenantId}
  and w.webhook_id = #{webhookId}

select webhook_id, tenant_id, name, url, secret_enc, event_type, payload_template,
       retry_count, timeout_ms, enabled, del_flag, create_by, create_time, update_by, update_time
from crm_outbound_webhook
where del_flag = '0'
  and tenant_id = #{tenantId}
  and webhook_id = #{webhookId}

